package com.ecole.gestion_scolaire.registration.controller; import com.ecole.gestion_scolaire.registration.dto.*; import com.ecole.gestion_scolaire.registration.service.RegistrationInfoService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/registrations/{registrationId}/info") public class RegistrationInfoController{private final RegistrationInfoService service;public RegistrationInfoController(RegistrationInfoService s){service=s;}@GetMapping @PreAuthorize("hasAuthority('INSCRIPTION_CONSULTER')") public RegistrationInfoResponse get(@PathVariable Long registrationId){return service.find(registrationId);}@PutMapping @PreAuthorize("hasAuthority('INSCRIPTION_COMPLETER')") public RegistrationInfoResponse save(@PathVariable Long registrationId,@Valid @RequestBody RegistrationInfoRequest r){return service.save(registrationId,r);}}
